    global tok
    r = urllib.request.Request(B + "/token", method="POST", data=b"")
    for _ in range(20):
        try:
            tok = json.load(urllib.request.urlopen(r))["token"]; return
        except urllib.error.HTTPError as e:
            log.append(("token", e.code, dict(e.headers), e.read()[:200])); time.sleep(float(e.headers.get("Retry-After", 1)))
    raise SystemExit("no token")
def req(path):
    global tok
    if tok is None: get_token()
    for _ in range(200):
        r = urllib.request.Request(B + path, headers={"Authorization": "Bearer " + tok})
